using System;using System.IO;using System.Linq;using System.Text;using System.Globalization;using System.Collections.Generic;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Security.Cryptography;using System.ComponentModel;
namespace CircuitoStudio {
[DataContract]public enum ResponseKind{[EnumMember] TimeSeconds,[EnumMember] EnergyA2s,[EnumMember] PeakKA}
[DataContract]public sealed class ResponsePoint{[DataMember]public double CurrentA{get;set;}[DataMember]public double Lower{get;set;}[DataMember]public double Upper{get;set;}public ResponsePoint Copy(){return (ResponsePoint)MemberwiseClone();}}
[DataContract]public sealed class ProtectionResponse {
[DataMember]public ResponseKind Kind{get;set;}[DataMember]public string Manufacturer{get;set;}[DataMember]public string Reference{get;set;}[DataMember]public double VoltageV{get;set;}[DataMember]public double FrequencyHz{get;set;}[DataMember]public PoleLayout Poles{get;set;}[DataMember]public double RatedA{get;set;}[DataMember]public string Settings{get;set;}[DataMember]public double? MagneticPickupA{get;set;}[DataMember]public double? DelaySettingSeconds{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Conditions{get;set;}[DataMember]public List<ResponsePoint> Points{get;set;}
public ProtectionResponse(){Manufacturer=Reference=Settings=Source=DataVersion=Conditions="";Points=new List<ResponsePoint>();}
public void Validate(){if(!Enum.IsDefined(typeof(ResponseKind),Kind)||!Enum.IsDefined(typeof(PoleLayout),Poles))throw new InvalidDataException("Tipo/polos da curva inválidos.");foreach(string text in new[]{Manufacturer,Reference,Settings,Source,DataVersion,Conditions})if(String.IsNullOrWhiteSpace(text)||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Curva exige fabricante, referência, ajustes, fonte, versão e condições (até2000 caracteres).");Project.Range(VoltageV,1,1e6,"tensão da curva");Project.Range(FrequencyHz,1,1000,"frequência da curva");Project.Range(RatedA,.001,1e9,"In da curva");if(MagneticPickupA.HasValue)Project.Range(MagneticPickupA.Value,.001,1e12,"ajuste magnético da curva");if(DelaySettingSeconds.HasValue)Project.Range(DelaySettingSeconds.Value,0,1e9,"retardo de ajuste da curva");if(Points==null||Points.Count<2||Points.Count>100000)throw new InvalidDataException("Informe de2 a100000 pontos de curva.");double previous=0;foreach(var point in Points){if(point==null)throw new InvalidDataException("Ponto ausente.");Project.Range(point.CurrentA,1e-12,1e15,"corrente da curva");Project.Range(point.Lower,1e-12,1e30,"banda inferior");Project.Range(point.Upper,point.Lower,1e30,"banda superior");if(point.CurrentA<=previous)throw new InvalidDataException("Correntes devem ser estritamente crescentes, sem duplicatas.");previous=point.CurrentA;}}
public ProtectionResponse Copy(){var copy=(ProtectionResponse)MemberwiseClone();copy.Points=Points==null?null:Points.Select(x=>x.Copy()).ToList();return copy;}
public ResponsePoint At(double currentA){Validate();Project.Range(currentA,1e-12,1e15,"corrente consultada");if(currentA<Points[0].CurrentA||currentA>Points[Points.Count-1].CurrentA)return null;int lo=0,hi=Points.Count-1;while(lo<hi){int mid=(lo+hi)/2;if(Points[mid].CurrentA<currentA)lo=mid+1;else hi=mid;}if(Points[lo].CurrentA==currentA)return Points[lo].Copy();var left=Points[lo-1];var right=Points[lo];double t=(Math.Log(currentA)-Math.Log(left.CurrentA))/(Math.Log(right.CurrentA)-Math.Log(left.CurrentA));return new ResponsePoint{CurrentA=currentA,Lower=Math.Exp(Math.Log(left.Lower)+t*(Math.Log(right.Lower)-Math.Log(left.Lower))),Upper=Math.Exp(Math.Log(left.Upper)+t*(Math.Log(right.Upper)-Math.Log(left.Upper)))};}
}
[DataContract]public sealed class ResponseBinding{[DataMember]public ProtectionResponse Curve{get;set;}[DataMember]public string Context{get;set;}public ResponseBinding Copy(){return new ResponseBinding{Curve=Curve.Copy(),Context=Context};}}
[DataContract]public sealed class ProtectionResponseSet {
[DataMember]public string Engine{get;set;}[DataMember]public ResponseBinding Time{get;set;}[DataMember]public ResponseBinding Energy{get;set;}[DataMember]public ResponseBinding Peak{get;set;}
public ProtectionResponseSet(){Engine=ProtectionResponses.EngineId;}
public ResponseBinding For(ResponseKind kind){return kind==ResponseKind.TimeSeconds?Time:kind==ResponseKind.EnergyA2s?Energy:Peak;}
public void Set(ResponseKind kind,ResponseBinding binding){if(kind==ResponseKind.TimeSeconds)Time=binding;else if(kind==ResponseKind.EnergyA2s)Energy=binding;else Peak=binding;}
public void Validate(){if(Engine!=ProtectionResponses.EngineId)throw new InvalidDataException("Revisão de curvas desconhecida.");foreach(ResponseKind kind in Enum.GetValues(typeof(ResponseKind))){var bind=For(kind);if(bind==null)continue;if(bind.Curve==null||bind.Curve.Kind!=kind||bind.Context==null||(bind.Context!=""&&(bind.Context.Length!=64||bind.Context.Any(x=>!Uri.IsHexDigit(x)))))throw new InvalidDataException("Vínculo de curva inválido.");bind.Curve.Validate();}}
public ProtectionResponseSet Copy(){return new ProtectionResponseSet{Engine=Engine,Time=Time==null?null:Time.Copy(),Energy=Energy==null?null:Energy.Copy(),Peak=Peak==null?null:Peak.Copy()};}
}
public sealed partial class Circuit{[DataMember(Order=99),Browsable(false)]public ProtectionResponseSet ProtectionResponses{get;set;}}
public static class ProtectionResponses {
public const string EngineId="cs-curvas-resposta-v1";
public const string Header="Kind;Manufacturer;Reference;VoltageV;FrequencyHz;Poles;RatedA;Settings;MagneticPickupA;DelaySettingSeconds;Source;DataVersion;Conditions;CurrentA;Lower;Upper";
public static string Title(ResponseKind kind){return kind==ResponseKind.TimeSeconds?"Tempo t-I":kind==ResponseKind.EnergyA2s?"Energia passante I²t":"Pico Ip";}
public static string Unit(ResponseKind kind){return kind==ResponseKind.TimeSeconds?"s":kind==ResponseKind.EnergyA2s?"A²s":"kA pico";}
public static string Hash<T>(T value){using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(stream,value);using(var hash=SHA256.Create())return String.Concat(hash.ComputeHash(stream.ToArray()).Select(x=>x.ToString("x2")));}}
static string Context(Circuit c,ProtectionResponse curve){var primary=c.Protection.BreakerSnapshot;if(primary!=null&&Same(primary.Rating.Manufacturer,curve.Manufacturer)&&Same(primary.Rating.Reference,curve.Reference))return Coordination.BaseConfiguration(c);var selected=c.SwitchgearSelection;if(selected!=null&&selected.Rating.IsFuse&&Same(selected.Rating.Manufacturer,curve.Manufacturer)&&Same(selected.Rating.Reference,curve.Reference))return Hash(selected);return "";}
static bool Same(string a,string b){return String.Equals((a??"").Trim(),(b??"").Trim(),StringComparison.OrdinalIgnoreCase);}
public static bool Matches(Project p,Circuit c,ResponseBinding binding){if(binding==null)return false;var curve=binding.Curve;curve.Validate();var board=p.Boards.SingleOrDefault(b=>b.Circuits.Contains(c));if(board==null||!BreakerSelection.ValidTopology(new CircuitResult{Circuit=c,Board=board},curve.Poles))return false;string current=Context(c,curve);if(current==""||binding.Context!=current||curve.VoltageV!=c.Voltage||curve.FrequencyHz!=p.Frequency)return false;var primary=c.Protection.BreakerSnapshot;if(primary!=null&&Same(primary.Rating.Manufacturer,curve.Manufacturer)&&Same(primary.Rating.Reference,curve.Reference))return curve.RatedA==c.BreakerA&&curve.Poles==primary.Rating.Poles&&(!curve.MagneticPickupA.HasValue||curve.MagneticPickupA.Value==c.Protection.MagneticTripA);var fuse=c.SwitchgearSelection;return fuse!=null&&curve.RatedA==fuse.Rating.RatedA&&curve.Poles==fuse.Rating.Poles&&!curve.MagneticPickupA.HasValue;}
public static void Attach(Project p,Circuit c,ProtectionResponse curve){p.Validate();if(!p.Boards.Any(b=>b.Circuits.Contains(c)))throw new InvalidDataException("Circuito fora do projeto.");curve.Validate();var candidate=c.ProtectionResponses==null?new ProtectionResponseSet():c.ProtectionResponses.Copy();candidate.Set(curve.Kind,new ResponseBinding{Curve=curve.Copy(),Context=Context(c,curve)});candidate.Validate();c.ProtectionResponses=candidate;}
public static string Describe(Project p,Circuit c){var set=c.ProtectionResponses;if(set==null)return "Sem curvas t-I/I²t/Ip adicionais.";set.Validate();var text=new StringBuilder("CURVAS t-I / I²t / Ip — "+EngineId+"\r\n");foreach(ResponseKind kind in Enum.GetValues(typeof(ResponseKind))){var binding=set.For(kind);if(binding==null){text.AppendLine(kind+": não informada.");continue;}var r=binding.Curve;text.AppendLine(kind+" ["+Unit(kind)+"] — "+r.Manufacturer+" / "+r.Reference+"; In="+r.RatedA+" A; "+r.VoltageV+" V; "+r.FrequencyHz+" Hz; "+BreakerSelection.PoleName(r.Poles)+". Ajustes declarados: "+r.Settings+"; magnético="+(r.MagneticPickupA.HasValue?r.MagneticPickupA.ToString():"não informado")+" A; retardo de ajuste="+(r.DelaySettingSeconds.HasValue?r.DelaySettingSeconds.ToString():"não informado")+" s. Fonte: "+r.Source+"; versão "+r.DataVersion+"; condições: "+r.Conditions+". "+r.Points.Count+" pontos; domínio "+r.Points[0].CurrentA+"–"+r.Points[r.Points.Count-1].CurrentA+" A. "+(Matches(p,c,binding)?"Identidade e contexto nominal correspondem; conferir demais ajustes e condições físicas.":"Referência sem vínculo nominal atual; não usar como curva comprovada do dispositivo selecionado."));}text.AppendLine("Bandas inferior/superior importadas, com interpolação log-log somente dentro do domínio; sem extrapolação, normalização ou escala automática de ajustes. Retardo de ajuste não é tempo total de eliminação da falta. Curvas registram dados de referência e não reconfiguram o dispositivo nem alteram automaticamente I²t, tempo ou pico do estudo. Bandas/curvas individuais não comprovam seletividade ou backup.");return text.ToString();}
static double Number(string text){double x;if(text.Contains('.')&&text.Contains(','))throw new InvalidDataException("Número ambíguo.");if(!Double.TryParse(text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out x)||Double.IsNaN(x)||Double.IsInfinity(x))throw new InvalidDataException("Número inválido.");return x;}
static double? Optional(string text){return String.IsNullOrWhiteSpace(text)?(double?)null:Number(text);}
static T EnumValue<T>(string text){try{var x=(T)Enum.Parse(typeof(T),text,true);if(Enum.IsDefined(typeof(T),x))return x;}catch{}throw new InvalidDataException("Tipo/polos inválidos.");}
public static ProtectionResponse Import(string file){if(new FileInfo(file).Length>32L*1024*1024)throw new InvalidDataException("Arquivo excede32 MiB.");var rows=CatalogData.Rows(File.ReadAllText(file,Encoding.UTF8).TrimStart('\uFEFF'));if(rows.Count<3||rows.Count>100001||String.Join(";",rows[0])!=Header)throw new InvalidDataException("Cabeçalho/tamanho inválido; informe pelo menos2 pontos.");ProtectionResponse result=null;string[] metadata=null;for(int i=1;i<rows.Count;i++){try{var x=rows[i];if(x.Length!=16)throw new InvalidDataException("Esperadas16 colunas.");if(result==null){metadata=x.Take(13).ToArray();result=new ProtectionResponse{Kind=EnumValue<ResponseKind>(x[0]),Manufacturer=x[1],Reference=x[2],VoltageV=Number(x[3]),FrequencyHz=Number(x[4]),Poles=EnumValue<PoleLayout>(x[5]),RatedA=Number(x[6]),Settings=x[7],MagneticPickupA=Optional(x[8]),DelaySettingSeconds=Optional(x[9]),Source=x[10],DataVersion=x[11],Conditions=x[12]};}else if(!metadata.SequenceEqual(x.Take(13)))throw new InvalidDataException("Metadados/ajustes devem ser iguais em todos os pontos do arquivo.");result.Points.Add(new ResponsePoint{CurrentA=Number(x[13]),Lower=Number(x[14]),Upper=Number(x[15])});}catch(Exception ex){throw new InvalidDataException("Ponto/registro "+i+": "+ex.Message,ex);}}result.Validate();return result;}
static string Quote(string x){return "\""+x.Replace("\"","\"\"")+"\"";}
public static void Export(ProtectionResponse curve,string file){if(curve!=null)curve.Validate();string full=Path.GetFullPath(file);Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{long bytes=3+Encoding.UTF8.GetByteCount(Header+"\r\n");using(var w=new StreamWriter(temp,false,new UTF8Encoding(true))){w.WriteLine(Header);if(curve!=null)foreach(var pt in curve.Points){var c=curve;string line=String.Join(";",new[]{c.Kind.ToString(),c.Manufacturer,c.Reference,c.VoltageV.ToString("R",CultureInfo.InvariantCulture),c.FrequencyHz.ToString("R",CultureInfo.InvariantCulture),c.Poles.ToString(),c.RatedA.ToString("R",CultureInfo.InvariantCulture),c.Settings,c.MagneticPickupA.HasValue?c.MagneticPickupA.Value.ToString("R",CultureInfo.InvariantCulture):"",c.DelaySettingSeconds.HasValue?c.DelaySettingSeconds.Value.ToString("R",CultureInfo.InvariantCulture):"",c.Source,c.DataVersion,c.Conditions,pt.CurrentA.ToString("R",CultureInfo.InvariantCulture),pt.Lower.ToString("R",CultureInfo.InvariantCulture),pt.Upper.ToString("R",CultureInfo.InvariantCulture)}.Select(Quote));bytes+=Encoding.UTF8.GetByteCount(line+"\r\n");if(bytes>32L*1024*1024)throw new InvalidDataException("Curva excede32 MiB; destino preservado.");w.WriteLine(line);}}if(File.Exists(full))File.Replace(temp,full,full+".bak");else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
}
